// The Supabase 'inventory' table has: id, model, vin, status, days_in_stock,
// price_aed, cost_aed, gross_margin, ... There is no brand/make/year column,
// so build the search query from what actually exists.
// This node runs once for ALL items. It used to read `$json`, which is only the
// FIRST inventory row -- so of twelve units in stock, exactly one (the Land
// Cruiser) was ever priced against the market and the other eleven were never
// scanned at all. The run went green every night regardless, because one item
// in and one item out looks exactly like success.
const out = [];
for (const row of $input.all()) {
  const item = row.json;
  const model = String(item.model || '').trim();
  if (!model) continue;   // nothing searchable; do not query 'undefined UAE price'
  out.push({ json: {
    id: item.id,
    model: model,
    vin: item.vin || null,
    localPrice: Number(item.price_aed) || null,
    daysInStock: Number(item.days_in_stock) || 0,
    searchQuery: `${model} price UAE dealership`
  } });
}
return out;

