// Runs ONCE PER ITEM. It used to run once for all of them and read `$json`,
// which is only the FIRST item -- so of sixteen scraped pages exactly one was
// ever parsed and the other fifteen were dropped without a trace. Combined with
// `Build Apify Query` scanning only the first of twelve units, the nightly
// "competitor intel" run was examining one page about one car and reporting
// success. That is why `competitors` has been empty since the day it was built.
//
// Per-item mode also fixes the pairing: `$('Node').item` resolves the ancestor
// of THIS item, where `.first()` always returned page one's metadata no matter
// which page we were parsing -- which is how a correctly-scraped page came back
// with someone else's source, or none.
const response = $json;

let original = {};
try { original = $('Build Apify Query').item.json || {}; } catch (e) { original = {}; }

let apifyItem = {};
try { apifyItem = $('Apify - Search Competitor Price').item.json || {}; } catch (e) { apifyItem = {}; }

let parsed = { price: null };
try { parsed = JSON.parse(response.choices?.[0]?.message?.content || '{}'); } catch (e) { /* keep default */ }

const meta   = apifyItem.metadata || {};
const jsonLd = meta.jsonLd || {};
const offers = jsonLd.offers || {};

/* A dealership LISTING page publishes an ItemList, not a single offer, so the
   prices live at @graph.itemListElement[].item.offers.price. Reading only the
   top-level offers.price found nothing on exactly the pages carrying the most
   prices. Walk the whole structure and take the lowest AED offer -- which is
   what the extraction prompt asks for anyway. */
function collectPrices(node, depth) {
  if (!node || depth > 8) return [];
  if (Array.isArray(node)) return node.flatMap(v => collectPrices(v, depth + 1));
  if (typeof node !== 'object') return [];
  let found = [];
  const cur = node.priceCurrency ? String(node.priceCurrency).toUpperCase() : null;
  if (node.price !== undefined && (!cur || cur === 'AED')) {
    const n = Number(String(node.price).replace(/[^0-9.]/g, ''));
    // Under 20k is a deposit, an accessory or a monthly instalment, not a car.
    if (Number.isFinite(n) && n >= 20000) found.push(n);
  }
  for (const k of Object.keys(node)) found = found.concat(collectPrices(node[k], depth + 1));
  return found;
}
const ldPrices = collectPrices(jsonLd, 0);
const ldPrice  = ldPrices.length ? Math.min(...ldPrices) : null;

const modelPrice = (typeof parsed.price === 'number' && parsed.price > 0) ? parsed.price : null;
const competitorPrice = ldPrice !== null ? ldPrice : modelPrice;
const priceFrom = ldPrice !== null ? 'schema.org JSON-LD' : 'model extraction';
const localPrice = original.localPrice ?? null;

/* The source is not a judgement call: the page's own hostname always exists.
   Asking the model to name the site from the first 6000 characters of markdown
   is what produced the null sources the guard below kept rejecting. */
let hostSource = null;
try {
  const u = String(meta.url || meta.canonicalUrl || '');
  if (u) hostSource = new URL(u).hostname.replace(/^www\./, '');
} catch (e) { /* not parseable */ }
const ldSeller = (offers.seller && typeof offers.seller.name === 'string') ? offers.seller.name.trim() : '';
const modelSource = typeof parsed.source === 'string' ? parsed.source.trim() : '';

/* A bot-detection interstitial is a scrape failure wearing a dealership's
   clothes -- "Pardon Our Interruption" once entered `competitors` as a rival. */
const BLOCK_PAGE = /pardon our interruption|just a moment|access denied|are you a robot|captcha|cloudflare|attention required|verify you are human|enable javascript|403 forbidden|too many requests|unusual traffic/i;
const NOT_A_NAME = /^(null|undefined|none|n\/?a|unknown|-{1,}|\s*)$/i;

/* A hostname always exists, which is exactly the trap: a Google results page
   has one too. The first real run filed `google.com` as a rival dealership
   quoting 105,200 for a Fortuner -- a search page's own snippet, not an offer
   anyone will honour. A competitor row is a claim the sales floor may act on,
   so the source has to be somewhere that actually sells cars. */
const NOT_A_SELLER = /^(www\.)?(google|bing|duckduckgo|yahoo|search|youtube|facebook|instagram|twitter|x|linkedin|tiktok|pinterest|reddit|quora|wikipedia|wikiwand|medium|blogspot|wordpress|tripadvisor|amazon|aliexpress|ebay)\./i;

const raw = ldSeller || hostSource || modelSource;
let source = raw;
let skipReason = null;

if (!raw)                      skipReason = 'the page carried no identifiable source';
else if (NOT_A_SELLER.test(raw + '.')) skipReason = `"${raw}" is a search or social site, not a seller`;
else if (NOT_A_NAME.test(raw)) skipReason = `the source was the placeholder "${raw}"`;
else if (BLOCK_PAGE.test(raw)) skipReason = `the page was a bot-detection interstitial ("${raw.slice(0, 60)}")`;
else if (raw.length > 80)      skipReason = 'the source read as prose, not a seller name';
if (skipReason) source = null;

/* No price is not intel either: a row with a null price cannot support an
   undercut claim, and every one written so far was noise in the table the
   dashboard reads. */
if (competitorPrice === null && !skipReason) skipReason = 'no price could be extracted from the page';

return { json: {
  id: original.id ?? null,
  model: original.model ?? null,
  pageUrl: meta.url || null,
  localPrice: localPrice,
  competitorPrice: competitorPrice,
  priceDiff: (competitorPrice !== null && localPrice !== null) ? (competitorPrice - localPrice) : null,
  competitorSource: source,
  currency: parsed.currency || 'AED',
  daysInStock: original.daysInStock ?? 0,
  priceFrom: priceFrom,
  usable: !skipReason,
  skipReason: skipReason,
} };

// Verify every node whose success this audit row is about to claim.
// This edge is the TRUE branch of 'Is This Real Intel?', so the intel row was
// just written here and both this node and its claim always run together.
// NOTE: 'Update Prices in Supabase' is NOT claimed. It is orphaned - nothing
// connects into 'Should Update Price?', so that whole sub-branch never runs and
// $('Update Prices in Supabase') would THROW.
const CLAIMED = [
  { node: 'Log Competitor Intel', what: 'competitors intel row', critical: true },
];

function check(c) {
  let it;
  try { it = $(c.node).item; }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!it) return { ...c, ok: false, why: 'node produced no items' };
  const j = it.json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);
const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

const base = $json;

// When the insert swallows, its output item is the error rather than the stored
// row, so `model` disappears and the audit summary degrades to 'a unit'. Carry
// the model forward from the parse step so the row still names the vehicle.
let p = {};
try { p = $('Parse AI Price').item.json || {}; } catch (e) { p = {}; }

return { json: {
  ...base,
  model: (base.model !== undefined && base.model !== null) ? base.model : (p.model || null),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' - ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
} };
